// pubspec.yaml: flutter_secure_storage: ^9.2.2
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

// Android — recommend EncryptedSharedPreferences (default in 9.x).
const _android = AndroidOptions(
  encryptedSharedPreferences: true,
  keyCipherAlgorithm: KeyCipherAlgorithm.RSA_ECB_PKCS1Padding,
  storageCipherAlgorithm: StorageCipherAlgorithm.AES_GCM_NoPadding,
  resetOnError: true,   // wipe corrupted entries rather than crash
);

// iOS — restrict access to 'after first unlock' — safer than 'always'.
const _ios = IOSOptions(
  accessibility: KeychainAccessibility.first_unlock_this_device,
);

final storage = FlutterSecureStorage(aOptions: _android, iOptions: _ios);

// ────── Basic use ──────
await storage.write(key: 'access_token', value: token);
final saved = await storage.read(key: 'access_token');
await storage.delete(key: 'access_token');
await storage.deleteAll();      // signout everything

// ────── Hive AES key stored securely ──────
Future<List<int>> hiveKey() async {
  final existing = await storage.read(key: 'hive_key_b64');
  if (existing != null) return base64Decode(existing);
  final fresh = Hive.generateSecureKey();
  await storage.write(key: 'hive_key_b64', value: base64Encode(fresh));
  return fresh;
}

// ────── Token store used by Dio AuthInterceptor ──────
class TokenStore {
  TokenStore(this._storage);
  final FlutterSecureStorage _storage;
  String? _access;
  Future<void> load() async { _access = await _storage.read(key: 'access'); }
  String? get access => _access;
  Future<void> save(String access, String refresh) async {
    _access = access;
    await _storage.write(key: 'access', value: access);
    await _storage.write(key: 'refresh', value: refresh);
  }
  Future<void> clear() async {
    _access = null;
    await _storage.deleteAll();
  }
}
